(function () {
  'use strict';

  // Nur einmal pro Seite, auch wenn das Skript versehentlich doppelt eingebunden ist
  if (window.__etChatGeladen) return;
  window.__etChatGeladen = true;

  // Die komplette Chat-Oberfläche (chat/chat-app.html inkl. eingebetteter
  // Schrift) — wird beim Build hier als String eingesetzt.
  var APP_HTML = "<!DOCTYPE html>\n<html lang=\"de\" data-theme=\"dark\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n  <title>EasyTraktor Assistent<\/title>\n  <!--\n    Chat-Oberfläche des EasyTraktor Assistenten. Läuft im iframe, das\n    easytraktor-chat.js beim ersten Öffnen erzeugt (srcdoc) — dadurch bleibt\n    das Chat-Design vom Seiten-Design getrennt.\n\n    Grundlage: index.html des TYPO3-Chats. Geändert gegenüber dem Original:\n      - Schrift Manrope statt Google-Font „Inter\", eingebettet beim Build\n        (kein externer Abruf)\n      - Verlauf wird beim Laden nicht mehr erneut gespeichert (verdoppelte sich)\n      - Layout füllt das Fenster vollständig (auch mobil im Vollbild)\n      - Schließen-Button im Kopf, ESC schließt auch innerhalb des Chats\n      - keine Debug-Ausgaben in der Konsole, verständliche Fehlermeldungen\n      - Speicher-Schlüssel mit Präfix „et-chat-\", Markenfarbe #EE7500\n      - Touch-Geräte: 16 px Eingabeschrift (sonst zoomt iOS), kein Enter-Hinweis\n  -->\n  <style>\n    @font-face{font-family:'Manrope';font-style:normal;font-weight:400 700;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');}\n\n    :root {\n      --bg: #0b0d10;\n      --bg-soft: #111418;\n      --card: rgba(255,255,255,0.06);\n      --text: #eef2f6;\n      --muted: #9aa4b2;\n      --brand: #EE7500;\n      --brand-700: #d46800;\n      --ring: rgba(238, 117, 0, 0.35);\n      --bot: rgba(255,255,255,0.08);\n      --user-grad-1: #f5922e;\n      --user-grad-2: #EE7500;\n      --scrollbar: rgba(255,255,255,0.15);\n      --line: rgba(255,255,255,0.08);\n    }\n    @media (prefers-color-scheme: light) {\n      :root {\n        --bg: #fff8f0;\n        --bg-soft: #fff1e6;\n        --card: #ffffff;\n        --text: #20262d;\n        --muted: #5a6675;\n        --bot: #f3f4f6;\n        --scrollbar: rgba(0,0,0,0.2);\n        --line: rgba(0,0,0,0.08);\n      }\n    }\n    [data-theme=\"light\"] {\n      --bg: #fff8f0;\n      --bg-soft: #fff1e6;\n      --card: #ffffff;\n      --text: #20262d;\n      --muted: #5a6675;\n      --bot: #f3f4f6;\n      --scrollbar: rgba(0,0,0,0.2);\n      --line: rgba(0,0,0,0.08);\n    }\n    [data-theme=\"dark\"] {\n      --bg: #0b0d10;\n      --bg-soft: #111418;\n      --card: rgba(255,255,255,0.06);\n      --text: #eef2f6;\n      --muted: #9aa4b2;\n      --bot: rgba(255,255,255,0.08);\n      --scrollbar: rgba(255,255,255,0.15);\n      --line: rgba(255,255,255,0.08);\n    }\n\n    * { box-sizing: border-box; }\n    html, body { height: 100%; }\n    body {\n      margin: 0;\n      font-family: 'Manrope', system-ui, -apple-system, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n      background:\n        radial-gradient(1200px 800px at 10% -10%, rgba(238, 117, 0, 0.12), transparent 50%),\n        radial-gradient(1000px 600px at 90% 110%, rgba(238, 117, 0, 0.10), transparent 50%),\n        var(--bg);\n      color: var(--text);\n      -webkit-font-smoothing: antialiased;\n    }\n\n    /* Füllt das Fenster: Kopf und Eingabe fest, Nachrichten dazwischen scrollbar */\n    .app {\n      height: 100%;\n      display: flex;\n      flex-direction: column;\n      background: var(--card);\n    }\n\n    .header {\n      flex: 0 0 auto;\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      padding: 14px 16px 14px 20px;\n      background: linear-gradient(180deg, rgba(255,255,255,0.06), transparent);\n      border-bottom: 1px solid var(--line);\n    }\n    .title { display: flex; gap: 12px; align-items: center; font-weight: 700; letter-spacing: 0.2px; }\n    .logo {\n      width: 34px; height: 34px; border-radius: 10px; display: grid; place-items: center;\n      background: linear-gradient(135deg, var(--user-grad-1), var(--user-grad-2));\n      box-shadow: 0 8px 22px -10px var(--ring);\n    }\n    .status { display: inline-flex; gap: 8px; align-items: center; font-size: 12px; font-weight: 500; color: var(--muted); }\n    .status-dot { width: 8px; height: 8px; border-radius: 999px; background: #2ecc71; box-shadow: 0 0 0 6px rgba(46, 204, 113, 0.15); }\n\n    .toolbar { display: flex; gap: 4px; align-items: center; }\n    .icon-btn {\n      appearance: none; border: 0; background: transparent; color: var(--muted);\n      padding: 8px; border-radius: 10px; cursor: pointer; display: grid; place-items: center;\n    }\n    .icon-btn:hover { background: rgba(255,255,255,0.08); color: var(--text); }\n    .icon-btn:focus-visible, .send-btn:focus-visible { outline: 2px solid var(--brand); outline-offset: 2px; }\n\n    .chat {\n      flex: 1 1 auto;\n      min-height: 0;\n      display: flex; flex-direction: column; gap: 12px;\n      overflow-y: auto; padding: 20px; scroll-behavior: smooth;\n      overscroll-behavior: contain;\n    }\n    .chat::-webkit-scrollbar { width: 8px; }\n    .chat::-webkit-scrollbar-thumb { background: var(--scrollbar); border-radius: 999px; }\n\n    .row { display: flex; gap: 10px; align-items: flex-end; }\n    .row.user { justify-content: flex-end; }\n    .avatar {\n      width: 32px; height: 32px; border-radius: 10px; flex: 0 0 32px; display: grid; place-items: center;\n      background: var(--bg-soft); color: var(--muted); border: 1px solid var(--line);\n    }\n    .stack { max-width: 100%; min-width: 0; }\n    .bubble {\n      max-width: min(75vw, 600px);\n      padding: 10px 14px; border-radius: 16px; position: relative;\n      line-height: 1.45; font-size: 15px;\n      box-shadow: 0 10px 25px -18px rgba(0,0,0,0.6), 0 0 0 1px rgba(255,255,255,0.06) inset;\n      animation: pop 160ms ease-out;\n      overflow-wrap: anywhere; white-space: pre-wrap;\n    }\n    .row.user .bubble { color: #fff; background: linear-gradient(135deg, var(--user-grad-1), var(--user-grad-2)); }\n    .row.bot .bubble { background: var(--bot); }\n    .row.hinweis .bubble { background: transparent; box-shadow: 0 0 0 1px var(--line) inset; color: var(--muted); }\n    .meta { font-size: 11px; color: var(--muted); margin-top: 4px; user-select: none; }\n    .row.user .meta { text-align: right; }\n\n    @keyframes pop { from { transform: translateY(6px) scale(.98); opacity: 0 } to { transform: translateY(0) scale(1); opacity: 1 } }\n\n    .composer {\n      flex: 0 0 auto;\n      padding: 14px; display: grid; grid-template-columns: 1fr auto; gap: 10px;\n      border-top: 1px solid var(--line);\n      background: linear-gradient(0deg, rgba(255,255,255,0.06), transparent);\n    }\n    .input {\n      display: flex; gap: 10px; align-items: center; background: var(--card);\n      border: 1px solid rgba(255,255,255,0.12); border-radius: 14px; padding: 10px 12px;\n      box-shadow: 0 1px 0 0 rgba(255,255,255,0.05) inset;\n      min-width: 0;\n    }\n    textarea {\n      resize: none; border: 0; outline: 0; background: transparent; color: var(--text);\n      font: 500 15px 'Manrope', system-ui, sans-serif; width: 100%; max-height: 200px;\n    }\n    textarea::placeholder { color: var(--muted); }\n    .send-btn {\n      appearance: none; border: 0; cursor: pointer; border-radius: 12px;\n      background: linear-gradient(135deg, var(--user-grad-1), var(--user-grad-2)); color: #fff;\n      padding: 12px 16px; font: 600 15px 'Manrope', system-ui, sans-serif; letter-spacing: .2px;\n      display: inline-flex; align-items: center; gap: 8px;\n      box-shadow: 0 10px 24px -12px var(--ring);\n      transition: transform .06s ease, box-shadow .2s ease;\n    }\n    .send-btn[disabled] { opacity: .6; cursor: not-allowed; box-shadow: none; }\n    .send-btn:hover:not([disabled]) { transform: translateY(-1px); box-shadow: 0 16px 30px -14px var(--ring); }\n\n    /* Tipp-Animation — eigene Klasse, damit der grüne Status-Punkt nicht mithüpft */\n    .typing { display: inline-flex; gap: 6px; align-items: center; }\n    .typing-dot { width: 6px; height: 6px; border-radius: 999px; background: var(--muted); opacity: .6; animation: pulse 1.4s infinite; }\n    .typing-dot:nth-child(2) { animation-delay: .2s }\n    .typing-dot:nth-child(3) { animation-delay: .4s }\n    @keyframes pulse { 0% { opacity: .2; transform: translateY(0) } 50% { opacity: .8; transform: translateY(-2px) } 100% { opacity: .2; transform: translateY(0) } }\n\n    .sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); border: 0; }\n\n    .pill {\n      display: inline-flex; align-items: center; gap: 8px; white-space: nowrap;\n      padding: 6px 10px; border-radius: 999px; font-size: 12px; color: var(--muted);\n      background: rgba(255,255,255,0.06); border: 1px solid var(--line);\n    }\n    .kbd { font-variant-numeric: lining-nums; font-family: ui-monospace, SFMono-Regular, Menlo, monospace; }\n\n    .footer-note { flex: 0 0 auto; text-align: center; color: var(--muted); font-size: 12px; padding: 0 12px 12px; }\n\n    /* Touch-Geräte (Handy, Tablet):\n       - 16 px Eingabeschrift, sonst zoomt iOS beim Antippen ins Feld\n       - kein „↵ zum Senden\"-Hinweis (Shift+Enter gibt es dort nicht)\n       Bewusst per pointer statt Bildschirmbreite: Media Queries messen im\n       iframe die Fensterbreite, nicht die des Geräts. */\n    @media (pointer: coarse) {\n      textarea { font-size: 16px; }\n      .pill { display: none; }\n    }\n    /* Schmales Fenster: Senden-Button nur als Symbol */\n    @media (max-width: 420px) {\n      .send-label { display: none; }\n      .send-btn { padding: 12px 14px; }\n      .chat { padding: 16px; }\n    }\n  <\/style>\n<\/head>\n<body>\n  <div class=\"app\" role=\"application\" aria-label=\"EasyTraktor Assistent\">\n    <header class=\"header\">\n      <div class=\"title\">\n        <div class=\"logo\" aria-hidden=\"true\">\n          <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\" aria-hidden=\"true\">\n            <path d=\"M3 14c0-3.866 3.134-7 7-7h4a7 7 0 1 1-7 7H3z\" fill=\"white\" opacity=\".9\"/>\n            <path d=\"M6 14a5 5 0 0 1 5-5h2a5 5 0 1 1-5 5H6z\" fill=\"#000\" opacity=\".15\"/>\n          <\/svg>\n        <\/div>\n        <div>\n          <div style=\"font-size:16px\">EasyTraktor Assistent<\/div>\n          <div class=\"status\" aria-live=\"polite\"><span class=\"status-dot\"><\/span> Verbunden<\/div>\n        <\/div>\n      <\/div>\n      <div class=\"toolbar\">\n        <button class=\"icon-btn\" id=\"themeToggle\" type=\"button\" title=\"Hell/Dunkel umschalten\" aria-label=\"Hell/Dunkel umschalten\">\n          <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"currentColor\" aria-hidden=\"true\"><path d=\"M12 3a1 1 0 0 1 1 1v2a1 1 0 1 1-2 0V4a1 1 0 0 1 1-1zm0 14a4 4 0 1 0 0-8 4 4 0 0 0 0 8zm8-5a1 1 0 0 1 1 1 1 1 0 1 1-1-1zM4 12a1 1 0 1 1-2 0 1 1 0 0 1 2 0zm15.657-6.657a1 1 0 1 1-1.414 1.414 1 1 0 0 1 1.414-1.414zM6.757 18.364a1 1 0 1 1-1.414 1.415 1 1 0 0 1 1.414-1.415zM20 20a1 1 0 0 1-1.707.707l-1.414-1.414A1 1 0 1 1 18.293 18.3L19.707 19.7A1 1 0 0 1 20 20zM6.121 4.707A1 1 0 0 1 4.707 6.12 1 1 0 1 1 6.12 4.707z\"/><\/svg>\n        <\/button>\n        <button class=\"icon-btn\" id=\"closeBtn\" type=\"button\" title=\"Chat schließen\" aria-label=\"Chat schließen\">\n          <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" aria-hidden=\"true\"><path d=\"M6 6l12 12M18 6L6 18\"/><\/svg>\n        <\/button>\n      <\/div>\n    <\/header>\n\n    <main id=\"chat\" class=\"chat\" aria-live=\"polite\" aria-relevant=\"additions\"><\/main>\n\n    <div class=\"composer\">\n      <div class=\"input\">\n        <label class=\"sr-only\" for=\"message\">Nachricht<\/label>\n        <textarea id=\"message\" rows=\"1\" autocomplete=\"off\"><\/textarea>\n        <span class=\"pill\"><span class=\"kbd\">↵<\/span> zum Senden<\/span>\n      <\/div>\n      <button class=\"send-btn\" id=\"sendBtn\" type=\"button\" aria-label=\"Senden\">\n        <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"currentColor\" aria-hidden=\"true\"><path d=\"M2.01 21 23 12 2.01 3 2 10l15 2-15 2z\"/><\/svg>\n        <span class=\"send-label\">Senden<\/span>\n      <\/button>\n    <\/div>\n    <div class=\"footer-note\">KI-Assistent – Antworten werden automatisch generiert.<\/div>\n  <\/div>\n\n  <script>\n  (function () {\n    'use strict';\n\n    var WEBHOOK_URL = 'https://automat.tec.zone/webhook/2877707c-3b7d-458b-bc3f-398a0eaa25b2';\n\n    // Speicher-Schlüssel mit eigenem Präfix: Die Chat-Seite läuft auf derselben\n    // Domain wie die Website und teilt sich deren localStorage.\n    var KEY_SESSION = 'et-chat-session';\n    var KEY_VERLAUF = 'et-chat-verlauf';\n    var KEY_THEME = 'et-chat-theme';\n    var MAX_VERLAUF = 200;\n    var TOUCH = !!(window.matchMedia && window.matchMedia('(pointer: coarse)').matches);\n\n    // localStorage kann in privaten Fenstern o. Ä. werfen — der Chat soll dann\n    // trotzdem funktionieren, nur ohne gespeicherten Verlauf.\n    function lesen(key) { try { return localStorage.getItem(key); } catch (e) { return null; } }\n    function schreiben(key, wert) { try { localStorage.setItem(key, wert); } catch (e) { /* ohne Speicher weiter */ } }\n\n    // Altlasten des TYPO3-Chats (gleiche Domain, alte Schlüssel) entfernen. Der\n    // alte Verlauf war durch einen Fehler vervielfacht und wird nicht übernommen.\n    // „sessionId\" bleibt stehen: zu allgemein, könnte einem anderen Skript gehören.\n    try { localStorage.removeItem('et-chat'); localStorage.removeItem('et-theme'); } catch (e) { /* egal */ }\n\n    // ── Hell/Dunkel ────────────────────────────────────────────────\n    var html = document.documentElement;\n    var themeGespeichert = lesen(KEY_THEME);\n    html.setAttribute('data-theme', /^(light|dark|auto)$/.test(themeGespeichert || '') ? themeGespeichert : 'dark');\n    document.getElementById('themeToggle').addEventListener('click', function () {\n      var jetzt = html.getAttribute('data-theme');\n      var neu = jetzt === 'dark' ? 'light' : jetzt === 'light' ? 'auto' : 'dark';\n      html.setAttribute('data-theme', neu);\n      schreiben(KEY_THEME, neu);\n    });\n\n    // ── Session ────────────────────────────────────────────────────\n    var sessionId = lesen(KEY_SESSION);\n    if (!sessionId) {\n      sessionId = (window.crypto && crypto.randomUUID)\n        ? crypto.randomUUID()\n        : Math.random().toString(36).slice(2) + Date.now().toString(36);\n      schreiben(KEY_SESSION, sessionId);\n    }\n\n    var chat = document.getElementById('chat');\n    var input = document.getElementById('message');\n    var sendBtn = document.getElementById('sendBtn');\n\n    input.placeholder = TOUCH ? 'Nachricht eingeben…' : 'Nachricht eingeben… (Shift+Enter für Zeilenumbruch)';\n\n    // ── Verlauf ────────────────────────────────────────────────────\n    function verlaufLesen() {\n      try { var v = JSON.parse(lesen(KEY_VERLAUF) || '[]'); return Array.isArray(v) ? v : []; }\n      catch (e) { return []; }\n    }\n    function verlaufSpeichern(text, sender, ts) {\n      var v = verlaufLesen();\n      v.push({ text: text, sender: sender, ts: ts.toISOString() });\n      schreiben(KEY_VERLAUF, JSON.stringify(v.slice(-MAX_VERLAUF)));\n    }\n\n    function uhrzeit(d) {\n      try { return d.toLocaleTimeString('de-DE', { hour: '2-digit', minute: '2-digit' }); }\n      catch (e) { return ''; }\n    }\n\n    var ICON_USER = '<svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"currentColor\" aria-hidden=\"true\"><path d=\"M12 12a5 5 0 1 0-5-5 5 5 0 0 0 5 5Zm0 2c-4 0-7 2-7 4v2h14v-2c0-2-3-4-7-4Z\"/><\/svg>';\n    var ICON_BOT = '<svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"currentColor\" aria-hidden=\"true\"><path d=\"M4 4h16v6H4zM4 12h10v8H4z\"/><\/svg>';\n\n    // opts.speichern === false: nicht in den Verlauf schreiben (beim\n    // Wiederherstellen und für Status-/Fehlerhinweise).\n    // opts.hinweis: dezente Darstellung für Status-/Fehlerhinweise.\n    function addMessage(text, sender, opts) {\n      opts = opts || {};\n      var ts = (opts.ts instanceof Date && !isNaN(opts.ts.getTime())) ? opts.ts : new Date();\n\n      var row = document.createElement('div');\n      row.className = 'row ' + sender + (opts.hinweis ? ' hinweis' : '');\n\n      var avatar = document.createElement('div');\n      avatar.className = 'avatar';\n      avatar.innerHTML = sender === 'user' ? ICON_USER : ICON_BOT;\n\n      var bubble = document.createElement('div');\n      bubble.className = 'bubble';\n      bubble.textContent = text;\n\n      var meta = document.createElement('div');\n      meta.className = 'meta';\n      meta.textContent = (sender === 'user' ? 'Du' : 'EasyTraktor') + ' • ' + uhrzeit(ts);\n\n      var stack = document.createElement('div');\n      stack.className = 'stack';\n      stack.appendChild(bubble);\n      stack.appendChild(meta);\n\n      if (sender === 'user') { row.appendChild(stack); row.appendChild(avatar); }\n      else { row.appendChild(avatar); row.appendChild(stack); }\n\n      chat.appendChild(row);\n      chat.scrollTop = chat.scrollHeight;\n\n      if (opts.speichern !== false) verlaufSpeichern(text, sender, ts);\n    }\n\n    function addTyping() {\n      var row = document.createElement('div');\n      row.className = 'row bot';\n      row.id = 'typing-row';\n      row.innerHTML = '<div class=\"avatar\">' + ICON_BOT + '<\/div>'\n        + '<div class=\"bubble\"><span class=\"typing\" aria-label=\"Der Assistent schreibt\">'\n        + '<span class=\"typing-dot\"><\/span><span class=\"typing-dot\"><\/span><span class=\"typing-dot\"><\/span>'\n        + '<\/span><\/div>';\n      chat.appendChild(row);\n      chat.scrollTop = chat.scrollHeight;\n    }\n    function removeTyping() {\n      var t = document.getElementById('typing-row');\n      if (t) t.remove();\n    }\n\n    // ── Senden ─────────────────────────────────────────────────────\n    function hinweis(text) { addMessage(text, 'bot', { speichern: false, hinweis: true }); }\n\n    function sendMessage() {\n      var text = input.value.trim();\n      if (!text || sendBtn.disabled) return;\n\n      addMessage(text, 'user');\n      input.value = '';\n      autoResize();\n      sendBtn.disabled = true;\n      addTyping();\n\n      fetch(WEBHOOK_URL, {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({ session_id: sessionId, message: text })\n      }).then(function (res) {\n        return res.text().then(function (raw) {\n          var data = null;\n          try { data = JSON.parse(raw); } catch (e) { data = null; }\n          if (Array.isArray(data) && data.length > 0) data = data[0];   // Array-Antwort: erstes Element\n          removeTyping();\n          if (res.ok && data && data.reply) {\n            addMessage(String(data.reply), 'bot');\n          } else if (!res.ok) {\n            hinweis('Da ist gerade etwas schiefgelaufen (Fehler ' + res.status + '). Bitte versuche es in einem Moment noch einmal.');\n          } else {\n            hinweis('Darauf habe ich gerade keine Antwort erhalten. Bitte versuche es noch einmal.');\n          }\n        });\n      }).catch(function () {\n        removeTyping();\n        hinweis('Die Verbindung zum Assistenten ist gerade gestört. Bitte prüfe deine Internetverbindung und versuche es noch einmal.');\n      }).then(function () {\n        sendBtn.disabled = false;\n        chat.scrollTop = chat.scrollHeight;\n      });\n    }\n\n    // Eingabefeld wächst mit dem Text (48–200 px)\n    function autoResize() {\n      input.style.height = 'auto';\n      input.style.height = Math.max(48, Math.min(input.scrollHeight, 200)) + 'px';\n    }\n    input.addEventListener('input', autoResize);\n\n    // Enter sendet, Shift+Enter macht einen Zeilenumbruch\n    input.addEventListener('keydown', function (e) {\n      if (e.key === 'Enter' && !e.shiftKey && !e.isComposing) {\n        e.preventDefault();\n        sendMessage();\n      }\n    });\n    sendBtn.addEventListener('click', sendMessage);\n\n    // ── Verbindung zur Website (easytraktor-chat.js) ───────────────\n    // Die Website setzt window.etChatHost = { close } und ruft etChatFocus().\n    function schliessen() {\n      if (window.etChatHost && typeof window.etChatHost.close === 'function') window.etChatHost.close();\n    }\n    document.getElementById('closeBtn').addEventListener('click', schliessen);\n    document.addEventListener('keydown', function (e) { if (e.key === 'Escape') schliessen(); });\n    // Wird aufgerufen, wenn das Fenster bereits sichtbar ist — daher direkt,\n    // ohne auf den nächsten Frame zu warten (der pausiert in Hintergrund-Tabs).\n    window.etChatFocus = function () {\n      autoResize();\n      try { input.focus({ preventScroll: true }); } catch (e) { /* egal */ }\n    };\n\n    // ── Start ──────────────────────────────────────────────────────\n    verlaufLesen().forEach(function (m) {\n      if (m && typeof m.text === 'string') addMessage(m.text, m.sender === 'user' ? 'user' : 'bot', { ts: new Date(m.ts), speichern: false });\n    });\n    if (!chat.children.length) {\n      addMessage('Hallo! Ich bin dein EasyTraktor KI Assistent. Wie kann ich helfen?', 'bot');\n    }\n    autoResize();\n    chat.scrollTop = chat.scrollHeight;\n  })();\n  <\/script>\n<\/body>\n<\/html>\n";

  var MOBIL = '(max-width: 767px)';

  var ICON_CHAT = '<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M4 4h16v10H7l-3 3V4z"/></svg>';
  var ICON_ZU = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18"/></svg>';

  // Alle Regeln hängen an den IDs des Chats — nichts wirkt auf die übrige Seite.
  var CSS = [
    '#et-chat-launcher{position:fixed;right:20px;bottom:20px;z-index:9999;width:56px;height:56px;margin:0;padding:0;',
    'border:0;border-radius:50%;background:#EE7500;color:#fff;display:grid;place-items:center;cursor:pointer;',
    'box-shadow:0 8px 24px rgba(0,0,0,.25);transition:background .15s ease,transform .15s ease;',
    '-webkit-tap-highlight-color:transparent}',
    '#et-chat-launcher:hover{background:#d46800;transform:translateY(-1px)}',
    '#et-chat-launcher:focus-visible{outline:3px solid rgba(238,117,0,.5);outline-offset:3px}',
    '#et-chat-launcher svg{display:block;width:22px;height:22px}',
    '#et-chat-panel{position:fixed;right:20px;bottom:86px;z-index:9999;',
    'width:min(620px,calc(100vw - 40px));height:min(70vh,720px);',
    'border-radius:16px;overflow:hidden;background:#0b0d10;box-shadow:0 20px 60px rgba(0,0,0,.35)}',
    '#et-chat-panel[hidden]{display:none}',
    '#et-chat-panel iframe{display:block;width:100%;height:100%;border:0;margin:0}',
    // Die schwebende Kontaktleiste der Website (Mail/Telefon, rechts) liegt auf
    // der höchsten Ebene und hat einen unsichtbaren, 250 px breiten Kasten — sie
    // würde am Desktop über dem Chat liegen und dort Klicks/Scrollen abfangen.
    // Solange der Chat offen ist, wird sie ausgeblendet. Gibt es die Klasse
    // nicht (mehr), passiert einfach nichts.
    'html.et-chat-offen .navigation-right.mobile-none{visibility:hidden}',
    // Handy: Vollbild. Der Button verschwindet (Schließen sitzt im Chat-Kopf),
    // die Seite dahinter scrollt nicht mit.
    '@media ' + MOBIL + '{',
    '#et-chat-panel{top:0;left:0;right:0;bottom:auto;width:100%;height:100%;height:100dvh;border-radius:0;box-shadow:none}',
    'html.et-chat-offen #et-chat-launcher{display:none}',
    'html.et-chat-offen,html.et-chat-offen body{overflow:hidden}',
    '}'
  ].join('');

  var btn, panel, frame, bereit = false, offen = false;
  var mobil = window.matchMedia ? window.matchMedia(MOBIL) : { matches: false };

  function init() {
    if (document.getElementById('et-chat-launcher')) return;

    var style = document.createElement('style');
    style.id = 'et-chat-styles';
    style.textContent = CSS;
    document.head.appendChild(style);

    panel = document.createElement('div');
    panel.id = 'et-chat-panel';
    panel.setAttribute('role', 'dialog');
    panel.setAttribute('aria-label', 'EasyTraktor Assistent');
    panel.hidden = true;

    btn = document.createElement('button');
    btn.id = 'et-chat-launcher';
    btn.type = 'button';
    btn.setAttribute('aria-controls', 'et-chat-panel');
    zeigeButton(false);
    btn.addEventListener('click', function () { offen ? schliessen() : oeffnen(); });

    document.body.appendChild(panel);
    document.body.appendChild(btn);

    document.addEventListener('keydown', function (e) {
      if (e.key === 'Escape' && offen) schliessen();
    });

    // Handy: Fensterhöhe an den sichtbaren Bereich anpassen, damit das
    // Eingabefeld bei offener Bildschirmtastatur nicht verdeckt wird.
    if (window.visualViewport) {
      window.visualViewport.addEventListener('resize', passeHoeheAn);
      window.visualViewport.addEventListener('scroll', passeHoeheAn);
    }
    if (mobil.addEventListener) mobil.addEventListener('change', passeHoeheAn);
  }

  // Beschriftung + Symbol des Buttons. Kein versteckter Text im Button — das
  // alte „sr-only" gab es auf der Website nicht, der Text wäre sichtbar gewesen.
  function zeigeButton(istOffen) {
    var text = istOffen ? 'Chat schließen' : 'Chat öffnen';
    btn.setAttribute('aria-label', text);
    btn.setAttribute('title', text);
    btn.setAttribute('aria-expanded', istOffen ? 'true' : 'false');
    btn.innerHTML = istOffen ? ICON_ZU : ICON_CHAT;
  }

  // Die Chat-Oberfläche wird erst beim ersten Öffnen erzeugt: Wer den Chat nicht
  // nutzt, lädt nichts davon, und bis zum Klick gibt es keinerlei Verbindung
  // zum Chat-Dienst.
  function oeffnen() {
    if (!frame) {
      frame = document.createElement('iframe');
      frame.title = 'EasyTraktor Assistent';
      frame.addEventListener('load', verbinden);
      frame.srcdoc = APP_HTML;
      panel.appendChild(frame);
    }
    offen = true;
    panel.hidden = false;
    document.documentElement.classList.add('et-chat-offen');
    zeigeButton(true);
    passeHoeheAn();
    if (bereit) fokussieren();
  }

  function schliessen() {
    offen = false;
    panel.hidden = true;
    document.documentElement.classList.remove('et-chat-offen');
    zeigeButton(false);
    passeHoeheAn();
    try { btn.focus({ preventScroll: true }); } catch (e) { /* egal */ }
  }

  // Die Chat-Oberfläche meldet sich über window.etChatHost zum Schließen
  // (Schließen-Button im Kopf, ESC im Chat) und nimmt etChatFocus() entgegen.
  function verbinden() {
    bereit = true;
    try { frame.contentWindow.etChatHost = { close: schliessen }; } catch (e) { /* egal */ }
    if (offen) fokussieren();
  }

  // Am Rechner direkt ins Eingabefeld; auf Touch-Geräten nicht, sonst springt
  // sofort die Bildschirmtastatur auf und verdeckt den Chat.
  function fokussieren() {
    if (window.matchMedia && window.matchMedia('(pointer: coarse)').matches) return;
    try { frame.contentWindow.etChatFocus && frame.contentWindow.etChatFocus(); } catch (e) { /* egal */ }
  }

  function passeHoeheAn() {
    var vv = window.visualViewport;
    if (offen && mobil.matches && vv) {
      panel.style.height = vv.height + 'px';
      panel.style.top = vv.offsetTop + 'px';
    } else {
      panel.style.height = '';
      panel.style.top = '';
    }
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
